// src/App.js
import React, { useState, useEffect } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate, useNavigate, useLocation } from "react-router-dom";
import './brand.css';

// Auth Components
import LoginPage        from './components/login';
import RegistrationPage from './components/registration';
import ApproveJoinPage  from './components/ApproveJoinPage';   // NEW

import './App.css';
import SubscriptionPage  from './components/subscription/subscriptionpage';
import ContactForm       from "./components/subscription/ContactForm";
import ForgotPasswordPage from './components/ForgotPassword';
import ResetPasswordPage  from './components/ResetPassword';

function App() {
  // ── Authentication State ──
  const [isAuthenticated, setIsAuthenticated] = useState(!!localStorage.getItem('userApiKey'));
  const [username,        setUsername]        = useState(localStorage.getItem('username') || '');

  useEffect(() => {
    const handleStorageChange = () => {
      const key             = localStorage.getItem('userApiKey');
      const storedUsername  = localStorage.getItem('username');
      setIsAuthenticated(!!key);
      setUsername(storedUsername || '');
    };

    window.addEventListener('storage', handleStorageChange);
    handleStorageChange();
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  // ── Login handler ──
  // After login, check if there's a pending approve-join redirect stored by ApproveJoinPage
  const handleLoginSuccess = (apiKey, userData) => {
    localStorage.setItem('userApiKey', apiKey);
    localStorage.setItem('username',   userData.username);
    localStorage.setItem('email',      userData.email);
    setIsAuthenticated(true);
    setUsername(userData.username);
  };

  // ── Logout ──
  const handleLogout = (navigateFunc) => {
    localStorage.removeItem('userApiKey');
    localStorage.removeItem('username');
    setIsAuthenticated(false);
    setUsername('');
    navigateFunc('/login');
  };

  const Logout = () => {
    const navigate = useNavigate();
    useEffect(() => { handleLogout(navigate); }, [navigate]);
    return <div>Logging out...</div>;
  };

  // ── Protected Route ──
  const ProtectedRoute = ({ children }) => {
    if (!isAuthenticated) return <Navigate to="/login" replace />;
    return children;
  };

  // ── Login page: after success, redirect to ?redirect= param if present ──
  // This handles the case where admin was sent to /login?redirect=/approve-join?token=...
  const LoginWithRedirect = () => {
    const location = useLocation();
    const navigate = useNavigate();

    if (isAuthenticated) {
      // Check for a post-login redirect target
      const params         = new URLSearchParams(location.search);
      const redirectTarget = params.get('redirect');
      if (redirectTarget) {
        return <Navigate to={decodeURIComponent(redirectTarget)} replace />;
      }
      return <Navigate to="/" replace />;
    }

    return (
      <LoginPage
        onLoginSuccess={(apiKey, userData) => {
          handleLoginSuccess(apiKey, userData);
          // After login, navigate to redirect target if present
          const params         = new URLSearchParams(location.search);
          const redirectTarget = params.get('redirect');
          navigate(redirectTarget ? decodeURIComponent(redirectTarget) : '/');
        }}
      />
    );
  };

  // ── External app redirect ──
  const RedirectToExternalApp = () => {
    const apiKey = localStorage.getItem('userApiKey');
    if (!apiKey) return <Navigate to="/login" replace />;
    window.location.href = `https://vertimonitor.dm-airtech.com/#apiKey=${apiKey}`;
    return null;
  };

  return (
    <Router>
      <Routes>

        {/* ── Auth routes ── */}
        <Route path="/login"           element={<LoginWithRedirect />} />
        <Route path="/forgot-password" element={<ForgotPasswordPage />} />
        <Route path="/reset-password"  element={<ResetPasswordPage />} />
        <Route path="/logout"          element={<Logout />} />

        <Route
          path="/register"
          element={isAuthenticated ? <Navigate to="/" replace /> : <RegistrationPage />}
        />

        {/* ── NEW: Admin approve/reject join request ──
            Public route — ApproveJoinPage handles its own auth check internally
            and redirects to /login if the admin isn't logged in               */}
        <Route path="/approve-join" element={<ApproveJoinPage />} />

        {/* ── Main: redirect to external app ── */}
        <Route
          path="/"
          element={
            <ProtectedRoute>
              <RedirectToExternalApp />
            </ProtectedRoute>
          }
        />

        {/* ── Protected pages ── */}
        <Route
          path="/subscribe"
          element={
            <ProtectedRoute>
              <SubscriptionPage />
            </ProtectedRoute>
          }
        />
        <Route
          path="/contact"
          element={
            <ProtectedRoute>
              <ContactForm />
            </ProtectedRoute>
          }
        />

        {/* ── Catch-all ── */}
        <Route
          path="*"
          element={isAuthenticated ? <Navigate to="/" replace /> : <Navigate to="/login" replace />}
        />

      </Routes>
    </Router>
  );
}

export default App;
